<?php
namespace App\Controllers\Ledger;
use App\Controllers\System\LayoutController;use App\Services\Ledger\AssetService;use Core\DbPdo;use InvalidArgumentException;use Throwable;
class AssetController{
 private AssetService $service;private LayoutController $layout;public function __construct(){$p=DbPdo::conn();$this->service=new AssetService($p);$this->layout=new LayoutController($p);}public function create():void{$this->page('create','자산등록');}public function index():void{$this->page('list','자산대장');}public function depreciation():void{$this->page('depreciation','감가상각');}public function transfer():void{$this->page('transfer','자산이동');}public function disposal():void{$this->page('disposal','자산처분');}
 public function apiList():void{$this->respond(fn()=>['success'=>true,'data'=>$this->service->list($_GET)]);}public function apiDetail():void{$this->respond(function(){$r=$this->service->detail(trim((string)($_GET['id']??'')));if(!$r)throw new InvalidArgumentException('자산을 찾을 수 없습니다.');return['success'=>true,'data'=>$r];});}public function apiOptions():void{$this->respond(fn()=>['success'=>true,'data'=>$this->service->options()]);}public function apiCreate():void{$this->respond(fn()=>$this->service->create($this->input()));}public function apiTransfer():void{$this->respond(fn()=>$this->service->transfer($this->input()));}public function apiDepreciate():void{$this->respond(fn()=>$this->service->depreciate($this->input()));}public function apiDispose():void{$this->respond(fn()=>$this->service->dispose($this->input()));}
 private function page(string$mode,string$title):void{$assetPageMode=$mode;ob_start();require PROJECT_ROOT.'/app/views/ledger/assets/index.php';$content=ob_get_clean();$this->layout->render(['pageTitle'=>$title,'content'=>$content,'pageStyles'=>$pageStyles??'','pageScripts'=>$pageScripts??'','layoutOptions'=>$layoutOptions??[]]);}private function input():array{$r=json_decode(file_get_contents('php://input')?:'{}',true);return is_array($r)?$r:$_POST;}private function respond(callable$c):void{try{$this->json($c());}catch(InvalidArgumentException $e){$this->json(['success'=>false,'message'=>$e->getMessage()],422);}catch(Throwable){$this->json(['success'=>false,'message'=>'자산관리 처리 중 오류가 발생했습니다.'],500);}}private function json(array$p,int$s=200):void{http_response_code($s);header('Content-Type: application/json; charset=UTF-8');echo json_encode($p,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}}
